 30→// ---------------------------------------------------------------------------
 31→// Loader
 32→// ---------------------------------------------------------------------------
 33→
 34→export const loader = async ({ request }: LoaderFunctionArgs) => {
 35→  const { session } = await authenticate.admin(request);
 36→  const shop = session.shop;
 37→
 38→  const [subscription, zipCount, shopSettings] = await Promise.all([
 39→    getShopSubscription(shop),
 40→    db.zipCode.count({ where: { shop } }),
 41→    db.shopSettings.findUnique({ where: { shop } }),
 42→  ]);
 43→
 44→  return {
 45→    subscription,
 46→    zipCount,
 47→    shop,
 48→    defaultBehavior: shopSettings?.defaultBehavior ?? "block",
 49→    notificationEmail: shopSettings?.notificationEmail ?? "",
 50→  };
 51→};
 52→
 53→// ---------------------------------------------------------------------------
 54→// Action
 55→// ---------------------------------------------------------------------------
 56→
 57→export const action = async ({ request }: ActionFunctionArgs) => {
 58→  const { session } = await authenticate.admin(request);
 59→  const shop = session.shop;
 60→
 61→  const formData = await request.formData();
 62→  const intent = formData.get("intent") as string;
 63→
 64→  try {
 65→    if (intent === "save-behavior") {
 66→      const defaultBehavior = formData.get("defaultBehavior") as string;
 67→      if (defaultBehavior !== "block" && defaultBehavior !== "allow") {
 68→        return { error: "Invalid value for defaultBehavior" };
 69→      }
 70→      await db.shopSettings.upsert({
 71→        where: { shop },
 72→        create: { shop, defaultBehavior },
 73→        update: { defaultBehavior },
 74→      });
 75→      return { success: true, intent };
 76→    }
 77→
 78→    if (intent === "save-notification") {
 79→      const notificationEmail =
 80→        (formData.get("notificationEmail") as string | null) ?? "";
 81→      await db.shopSettings.upsert({
 82→        where: { shop },
 83→        create: { shop, notificationEmail: notificationEmail || null },
 84→        update: { notificationEmail: notificationEmail || null },
 85→      });
 86→      return { success: true, intent };
 87→    }
 88→
 89→    return { error: "Unknown intent" };
 90→  } catch {
 91→    return { error: "Failed to save settings. Please try again." };
 92→  }
 93→};
 94→
 95→// ---------------------------------------------------------------------------
 96→// Component
 97→// ---------------------------------------------------------------------------
 98→
 99→export default function SettingsPage() {
100→  const { subscription, zipCount, shop, defaultBehavior, notificationEmail } =
101→    useLoaderData<typeof loader>();
102→  const navigate = useNavigate();
103→  const shopify = useAppBridge();
104→  const limits = PLAN_LIMITS[subscription.planTier];
105→
106→  // Fetchers — one per save section so loading states stay independent
107→  const behaviorFetcher = useFetcher<typeof action>();
108→  const notificationFetcher = useFetcher<typeof action>();
109→
110→  // Local controlled state
111→  const [behaviorValue, setBehaviorValue] = useState(defaultBehavior);
112→  const [emailValue, setEmailValue] = useState(notificationEmail);
113→
114→  const isSavingBehavior = behaviorFetcher.state !== "idle";
115→  const isSavingNotification = notificationFetcher.state !== "idle";
116→  const isSaving = isSavingBehavior || isSavingNotification;
117→
118→  // Track dirty state
119→  const isDirty =
120→    behaviorValue !== defaultBehavior || emailValue !== notificationEmail;
121→
122→  // Toast on success
123→  useEffect(() => {
124→    if (
125→      behaviorFetcher.data &&
126→      "success" in behaviorFetcher.data &&
127→      behaviorFetcher.data.success
128→    ) {
129→      shopify.toast.show("Settings saved");
130→    }
131→  }, [behaviorFetcher.data, shopify]);
132→
133→  useEffect(() => {
134→    if (
135→      notificationFetcher.data &&
136→      "success" in notificationFetcher.data &&
137→      notificationFetcher.data.success
138→    ) {
139→      shopify.toast.show("Settings saved");
140→    }
141→  }, [notificationFetcher.data, shopify]);
142→
143→  const handleBehaviorChange = useCallback(
144→    (value: string) => setBehaviorValue(value),
145→    [],
146→  );
147→
148→  const handleEmailChange = useCallback(
149→    (value: string) => setEmailValue(value),
150→    [],
151→  );
152→
153→  const handleSaveAll = useCallback(() => {
154→    if (behaviorValue !== defaultBehavior) {
155→      const fd = new FormData();
156→      fd.append("intent", "save-behavior");
