243→                  </BlockStack>
244→                  <Button
245→                    variant="primary"
246→                    onClick={() => navigate("/app/pricing")}
247→                  >
248→                    {subscription.planTier === "free" || subscription.planTier === "starter"
249→                      ? "Upgrade Plan"
250→                      : "Manage Plan"}
251→                  </Button>
252→                </InlineStack>
253→              </BlockStack>
254→            </Card>
255→          </Layout.Section>
256→
257→          {/* ----------------------------------------------------------------
258→              Section 2: Default Behavior for Unknown Zip Codes (NEW)
