131→// ─── Action ───────────────────────────────────────────────────────────────────
132→
133→export const action = async ({ request }: ActionFunctionArgs): Promise<
134→  | { error: string }
135→  | { success: boolean; message: string }
136→  | null
137→> => {
138→  const { session, billing } = await authenticate.admin(request);
139→  const shop = session.shop;
140→  const formData = await request.formData();
141→  const intent = String(formData.get("intent"));
142→
143→  if (intent === "subscribe") {
144→    const plan = String(formData.get("plan"));
145→    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
146→    try {
147→      /* eslint-disable @typescript-eslint/no-explicit-any */
148→      // billing.request() throws a redirect Response to Shopify's
149→      // billing confirmation page — we must let it propagate.
150→      await billing.request({
151→        plan: plan as any,
152→        isTest: process.env.NODE_ENV !== "production",
153→        returnUrl,
154→      });
155→      /* eslint-enable @typescript-eslint/no-explicit-any */
156→      return null;
157→    } catch (error) {
158→      // Re-throw Response redirects so React Router / App Bridge handles them
159→      if (error instanceof Response) throw error;
160→      // BillingError has errorData with Shopify userErrors
161→      const errorData = (error as { errorData?: Array<{ field?: string; message?: string }> }).errorData;
162→      const details = errorData?.map((e) => e.message).join(", ");
163→      const message = details || (error instanceof Error ? error.message : String(error));
164→
165→      // Provide a helpful message for common billing errors
166→      if (message.includes("Custom apps cannot use the Billing API")) {
167→        return {
168→          error: "Billing is not available for custom apps. Please change your app distribution to 'Public' in the Shopify Partner Dashboard.",
169→        };
170→      }
171→      return {
172→        error: `Failed to initiate subscription: ${message}`,
173→      };
174→    }
175→  }
176→
177→  // Set plan directly in database (for custom apps where Billing API is unavailable)
178→  if (intent === "test-set-plan") {
179→    const tier = String(formData.get("tier")) as import("../plans").PlanTier;
180→    const validTiers = ["free", "starter", "pro", "ultimate"];
181→    if (!validTiers.includes(tier)) {
182→      return { error: `Invalid plan tier: ${tier}` };
183→    }
184→    const planId = tier === "free" ? "free" : `${tier.charAt(0).toUpperCase() + tier.slice(1)} Monthly`;
185→    await db.subscription.upsert({
186→      where: { shop },
187→      create: { shop, planId, billingInterval: "monthly", status: "active" },
188→      update: { planId, billingInterval: "monthly", status: "active", shopifySubscriptionId: null },
189→    });
190→    return { success: true, message: `Plan set to ${tier.charAt(0).toUpperCase() + tier.slice(1)}.` };
191→  }
192→
193→  if (intent === "cancel") {
194→    try {
195→      const sub = await getShopSubscription(shop);
196→      if (sub.shopifySubscriptionId) {
197→        await billing.cancel({
198→          subscriptionId: sub.shopifySubscriptionId,
199→          isTest: process.env.NODE_ENV !== "production",
200→          prorate: true,
201→        });
202→      }
203→      await cancelShopSubscription(shop);
204→      return {
205→        success: true,
206→        message: "Subscription cancelled. You are now on the Free plan.",
207→      };
208→    } catch {
209→      return { error: "Failed to cancel subscription. Please try again." };
210→    }
211→  }
212→
213→  return null;
214→};
