233→type PlanCardProps = {
234→  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
235→  isAnnual: boolean;
236→  currentTier: string;
237→  onSubscribe: (planName: string) => void;
238→  onRequestCancel: () => void;
239→  loadingPlan: string | null;
240→};
241→
242→function PlanCard({
243→  plan,
244→  isAnnual,
245→  currentTier,
246→  onSubscribe,
247→  onRequestCancel,
248→  loadingPlan,
249→}: PlanCardProps) {
250→  const isCurrent = currentTier === plan.id;
251→  const isBestValue = "bestValue" in plan && plan.bestValue;
252→  const isCurrentPaid = currentTier !== "free";
253→  const isDowngradeToFree = plan.id === "free" && isCurrentPaid;
254→
255→  const TIER_ORDER: Record<string, number> = {
256→    free: 0,
257→    starter: 1,
258→    pro: 2,
259→    ultimate: 3,
260→  };
261→  const isUpgrade =
262→    !isCurrent &&
263→    plan.id !== "free" &&
