 23→/**
 24→ * Get (or create) the subscription record for a shop from the DB.
 25→ */
 26→export async function getShopSubscription(
 27→  shop: string,
 28→): Promise<ShopSubscription> {
 29→  const sub = await db.subscription.upsert({
 30→    where: { shop },
 31→    update: {},
 32→    create: {
 33→      shop,
 34→      planId: PLAN_FREE,
 35→      billingInterval: "monthly",
 36→      status: "active",
 37→    },
 38→  });
 39→
 40→  const planTier = getPlanTier(sub.planId) ;
 41→  return {
 42→    planId: sub.planId,
 43→    planTier,
 44→    billingInterval: sub.billingInterval,
 45→    shopifySubscriptionId: sub.shopifySubscriptionId,
 46→    status: sub.status,
 47→    trialEndsAt: sub.trialEndsAt,
 48→    limits: PLAN_LIMITS[planTier],
 49→  };
 50→}
 51→
 52→/**
 53→ * Sync the subscription from Shopify billing check result into our DB.
 54→ * Returns the updated ShopSubscription.
 55→ */
 56→export async function syncSubscriptionFromShopify(
 57→  shop: string,
 58→  appSubscriptions: Array<{ id: string; name: string; status: string }>,
 59→): Promise<ShopSubscription> {
 60→  const activeSub = appSubscriptions.find((s) => s.status === "ACTIVE");
 61→  const frozenSub = !activeSub
 62→    ? appSubscriptions.find((s) => s.status === "FROZEN")
 63→    : undefined;
 64→  const pendingSub = !activeSub && !frozenSub
 65→    ? appSubscriptions.find((s) => s.status === "PENDING")
 66→    : undefined;
 67→
 68→  const matchedSub = activeSub ?? frozenSub ?? pendingSub ?? null;
 69→
 70→  let planId = PLAN_FREE;
 71→  let billingInterval = "monthly";
 72→  let shopifySubscriptionId: string | null = null;
 73→  let status = "active";
 74→
 75→  if (matchedSub) {
 76→    // For FROZEN/PENDING keep the plan but reflect the real status.
 77→    // For ACTIVE, this is the normal path.
 78→    planId = matchedSub.name;
 79→    shopifySubscriptionId = matchedSub.id;
 80→    status = matchedSub.status.toLowerCase();
 81→    billingInterval =
 82→      planId.toLowerCase().includes("annual") ? "annual" : "monthly";
 83→  }
 84→
 85→  const planTier = getPlanTier(planId) ;
 86→
 87→  await db.subscription.upsert({
 88→    where: { shop },
 89→    create: {
 90→      shop,
 91→      planId,
 92→      billingInterval,
 93→      shopifySubscriptionId,
 94→      status,
 95→    },
 96→    update: {
 97→      planId,
 98→      billingInterval,
 99→      shopifySubscriptionId,
100→      status,
101→    },
102→  });
103→
104→  return {
105→    planId,
106→    planTier,
107→    billingInterval,
108→    shopifySubscriptionId,
109→    status,
110→    trialEndsAt: null,
111→    limits: PLAN_LIMITS[planTier],
112→  };
113→}
